/* Generated by gen_tiles.py -- do not hand-edit. */
/* Re-run it (make tiles) after changing the art; the output is
 * committed so the build needs no Python. */

#ifndef MJ_ART_H
#define MJ_ART_H

#include <stdint.h>

/*
 * The pictures on the faces, at each size. A face is a list of
 * PARTS, one per colour it uses: a 1bpp mask, cropped to its
 * bounding box, at (x, y) from the face's top-left. Rows are one
 * uint32_t each, LEAST significant bit leftmost. Part i's rows are
 * mj_art_rows[part.off .. part.off + part.h).
 *
 * Faces are numbered as mj_game.h's MJ_F_*. The parts of face f at
 * size s are mj_art_parts[first[f] .. first[f + 1]).
 */

#define MJ_GC_INK   1
#define MJ_GC_RED   2
#define MJ_GC_GREEN 3
#define MJ_GC_BLUE  4

#define MJ_ART_SIZES 2
#define MJ_ART_SMALL 0   /* 20x26, depth 3 */
#define MJ_ART_LARGE 1   /* 30x40, depth 4 */

typedef struct {
	uint8_t  face_w, face_h, depth;
	uint16_t first[43];
} mj_art_size_t;

typedef struct {
	uint8_t  col, x, y, w, h;
	uint16_t off;
} mj_art_part_t;

extern const mj_art_size_t mj_art[MJ_ART_SIZES];
extern const mj_art_part_t mj_art_parts[160];
extern const uint32_t mj_art_rows[2794];

#endif
